static int16_t helm_dial_span_now(void)
{
    int16_t span;

    if (s_sh.dial_lock == 1) {
        span = (int16_t)s_sh.dial_phase;
    } else {
        span = (int16_t)((HELM_DIAL_SPAN * (int)s_sh.dial_kph10)
                         / (HELM_DIAL_MAX_KPH * 10));
    }

    if (span < 0) {
        return 0;
    }

    if (span > HELM_DIAL_SPAN) {
        return HELM_DIAL_SPAN;
    }

    return span;
}

