void helm_shell_set_paused(bool paused)
{
    if (s_sh.paused == paused) {
        return;
    }

    if (paused && !s_sh.paused) {
        myvendor_sound_pause();
    }

    s_sh.paused = paused;
    if (s_sh.ui_covered) {
        return;
    }

    /* 只翻暂停条，避免从菜单/保存框回来后整页 apply_view 卡住。 */
    helm_pause_dock_apply();
    helm_nums_defer_begin();
}

