        myvendor_devctl_power_cut();
        return;
    }

    s_off = lv_obj_create(top);
    lv_obj_remove_style_all(s_off);
    lv_obj_set_size(s_off, PAGE_HOR_RES, PAGE_VER_RES);
    lv_obj_align(s_off, LV_ALIGN_TOP_LEFT, 0, 0);
