    lv_obj_add_event_cb(s_off, helm_pwr_off_deleted, LV_EVENT_DELETE, NULL);
    lv_obj_set_style_opa(s_off, LV_OPA_TRANSP, 0);

    helm_splash_build(&s_off_sp, s_off);
    /* 底色跟主题（用户 2026-09-26 晚："开关机界面也[要]受主题变化影响"）：
