static void dial_content(int mode)
{
    char buf[64];
    const int b = s_batt;

    if (UD.name == NULL) {
        return;
    }
    lv_label_set_text(UD.name, mode_name(mode));
    dial_title_layout(mode);
    lv_label_set_text(UD.desc, mode_desc(mode));
    hfi_set(UD.icon, mode_icon(mode));
    lv_obj_set_style_text_color(UD.icon, lv_color_hex(C_DEEP[mode]), 0);

    switch (mode) {
        case M_RIDE:
            snprintf(buf, sizeof(buf), "%.1f",
                     s_rec_n > 0 ? s_recs[0].dist : 42.6);
            break;
        case M_NAV:
            snprintf(buf, sizeof(buf), "8.4");
            break;
        case M_RECORD:
            snprintf(buf, sizeof(buf), "%.1f", week_total());
            break;
        default:
            snprintf(buf, sizeof(buf), "%d", b);
            break;
    }
    lv_label_set_text(UD.value, buf);
    lv_label_set_text(UD.unit, mode == M_SET ? "%" : "km");
    hub_value_layout();

    switch (mode) {
        case M_RIDE:
            snprintf(buf, sizeof(buf), "本周 %.1f km · 电量 %d%%",
                     week_total(), b);
            break;
        case M_NAV:
            snprintf(buf, sizeof(buf), "全程 10.0 km · 电量 %d%%", b);
            break;
        case M_RECORD:
            snprintf(buf, sizeof(buf), "本周 %d 次 · 电量 %d%%", week_rides(),
                     b);
            break;
        default:
            snprintf(buf, sizeof(buf), "固件 v1.2.6 · 电量 %d%%", b);
            break;
    }
    lv_label_set_text(UD.sub, buf);

    for (int i = 0; i < 4; i++) {
        const bool sel = (i == mode);

        lv_obj_set_style_text_font(UD.labels[i],
                                   F(sel ? PX_BODY : PX_SMALL), 0);
        lv_obj_set_style_text_color(UD.labels[i],
                                    lv_color_hex(sel ? P_INK : P_MUTE), 0);
    }
    s_shown_mode = mode;
}

static void dial_status_refresh(void)
{
    char buf[24];

    if (UD.gps_l == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%d", s_gps);
    lv_label_set_text(UD.gps_l, buf);
    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    lv_label_set_text(UD.batt_l, buf);
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    lv_label_set_text(UD.time_l, buf);
    if (UD.live != NULL) {
        if (R.active) {
            lv_obj_remove_flag(UD.live, LV_OBJ_FLAG_HIDDEN);
            lv_obj_remove_flag(UD.live_bar, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(UD.live, LV_OBJ_FLAG_HIDDEN);
            lv_obj_add_flag(UD.live_bar, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

static void dial_build(void)
{
    memset(&UD, 0, sizeof(UD));
    s_screen = SCR_DIAL;
    d_bg(s_scr, P_PAPER);
    TOP(s_scr, "模式", "01 / 04");
    UD.top_l = lv_obj_get_child(s_scr, 0);
    UD.top_r = lv_obj_get_child(s_scr, 1);

    UD.cx = 120;
    UD.cy = 146;
    UD.d = 160;
    s_angle = s_mode * 90;
    UD.angle = s_angle;

    /* 整圈未选轨道 + 选中扇区（浅 20% + 深色 2px 外沿）。 */
    UD.ring = RING(s_scr, UD.cx, UD.cy, 160, 2, P_TRACK);
    dial_sector(s_mode, LV_OPA_COVER, &UD.fill, &UD.trk);

    /* 24 刻度：每 15°，整点 3px。 */
    for (int i = 0; i < 24; i++) {
        const bool major = (i % 6 == 0);

        UD.tick[i] = LINE(s_scr, UD.tick_pts[i], 2, major ? 3 : 1,
                          major ? P_INK : P_TICK);
    }
    /* 舵柄：中心到外圈 + 8px 横杆。 */
    UD.ptr = LINE(s_scr, UD.ptr_pts, 2, 3, P_INK);
    UD.cross = LINE(s_scr, UD.cross_pts, 2, 3, P_INK);

    /* 盘心：图标底 + 模式名 / 描述 / 主值 / 副行，装进一个容器方便整体淡入。 */
    UD.hub = lv_obj_create(s_scr);
    lv_obj_remove_style_all(UD.hub);
    lv_obj_set_pos(UD.hub, 40, 88);
    lv_obj_set_size(UD.hub, 160, 108);
    lv_obj_remove_flag(UD.hub, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(UD.hub, LV_OBJ_FLAG_CLICKABLE);

    {
        /* 标题：文字 160 宽居中；26px 图标由 dial_title_layout() 摆到左侧。 */
        UD.chip = NULL;
        UD.icon = hfi_create_px(UD.hub, mode_icon(s_mode), 26, 0, 0,
                                C_DEEP[s_mode]);
        UD.name = LW(UD.hub, "", PX_TITLE, P_INK, 0, 0, 160,
                     LV_TEXT_ALIGN_CENTER);
    }
    UD.desc = LW(UD.hub, "", PX_SMALL, P_MUTE, 0, 38, 160,
                 LV_TEXT_ALIGN_CENTER);
    {
        /* 22px 数字 + 11px 单位：共用基线（hub_value_layout）。 */
        UD.value = L(UD.hub, "", PX_VALUE, P_INK, 0, 55);
        UD.unit = L(UD.hub, "", PX_MICRO, P_MUTE, 0, 66);
    }
    HAIR(UD.hub, 64, 87, 32);
    UD.sub = LW(UD.hub, "", PX_MICRO, P_MUTE, 0, 92, 160,
                LV_TEXT_ALIGN_CENTER);

    /* 模式名：4 个方位，选中 15px。 */
    {
        static const int lx[4] = { 0, 1, 0, -1 };
        static const int ly[4] = { -1, 0, 1, 0 };

        for (int i = 0; i < 4; i++) {
            UD.labels[i] = LW(s_scr, mode_name(i), PX_SMALL, P_MUTE,
                              120 + lx[i] * 96 - 20, 146 + ly[i] * 104 - 8,
                              40, LV_TEXT_ALIGN_CENTER);
        }
    }

    /* 骑行中标记（顶栏，开始骑行后才出现）。 */
    UD.live_bar = B(s_scr, 76, 15, 3, 10, C_DEEP[M_RECORD],
                    LV_OPA_COVER, 1);
    UD.live = L(s_scr, "骑行中", PX_MICRO, P_MUTE, 84, 13);
    lv_obj_add_flag(UD.live, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(UD.live_bar, LV_OBJ_FLAG_HIDDEN);

    /* 底部状态带：三组按 24..216 均分（组宽 34/44/49，间隙 32），
     * 图标盒中心 274，11px 文字行盒中心也落在 274。 */
    UD.band = B(s_scr, 0, 262, 240, 24, P_CARD, LV_OPA_COVER, 0);
    HAIR(s_scr, 0, 262, 240);
    hfi_create(s_scr, HELM_ICON_GPS, 34, 274, C_DEEP[M_NAV]);
    UD.gps_l = L(s_scr, "12", PX_MICRO, P_INK, 46, 267);
    (void)B(s_scr, 74, 266, 3, 16, C_DEEP[M_NAV], LV_OPA_COVER, 1);
    hfi_create(s_scr, HELM_ICON_BATTERY, 100, 274, C_DEEP[M_RIDE]);
    UD.batt_l = L(s_scr, "86%", PX_MICRO, P_INK, 112, 267);
    (void)B(s_scr, 151, 266, 3, 16, C_DEEP[M_RECORD], LV_OPA_COVER, 1);
    hfi_create(s_scr, HELM_ICON_CLOCK, 177, 274, P_INK);
    UD.time_l = L(s_scr, "14:32", PX_MICRO, P_INK, 189, 267);

    dial_content(s_mode);
    dial_geometry(120, 146, 160, 255);
    dial_status_refresh();
    {
        char buf[24];

        snprintf(buf, sizeof(buf), "%02d / 04", s_mode + 1);
        lv_label_set_text(UD.top_r, buf);
    }
}

