static void elev_build(void)
{
    lv_obj_t *cv;
    const double step = ELEV_VIEW_M / (double)(ELEV_PROF_N - 1);
    double gain = 0;
    double mn;
    double mx;
    int peak = 0;
    char buf[32];

    d_bg(s_scr, P_PAPER);
    TOP(s_scr, "海拔", "前方 2 km");
    elev_profile_gen();
    mn = s_elev[0];
    mx = s_elev[0];
    for (int i = 0; i + 1 < ELEV_PROF_N; i++) {
        if (s_elev[i + 1] > s_elev[i]) {
            gain += s_elev[i + 1] - s_elev[i];
        }
    }
    for (int i = 1; i < ELEV_PROF_N; i++) {
        if (s_elev[i] < mn) mn = s_elev[i];
        if (s_elev[i] > mx) {
            mx = s_elev[i];
            peak = i;
        }
    }

    L(s_scr, "海拔 m", PX_MICRO, P_MUTE, 24, 40);
    snprintf(buf, sizeof(buf), "%d–%d m", (int)lround(mn), (int)lround(mx));
    LW(s_scr, buf, PX_MICRO, P_MUTE, 120, 40, 96, LV_TEXT_ALIGN_RIGHT);

    /* 当前位置竖线 + 大图（190×150）。 */
    (void)B(s_scr, 24, 56, 2, ELEV_BIG_H, P_INK, LV_OPA_COVER, 0);
    cv = lv_canvas_create(s_scr);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(cv, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_pos(cv, 26, 56);
    lv_canvas_set_buffer(cv, s_elev_big_cbuf, ELEV_BIG_W, ELEV_BIG_H,
                         LV_COLOR_FORMAT_RGB565);
    lv_obj_set_size(cv, ELEV_BIG_W, ELEV_BIG_H);
    elev_canvas_paint(cv, ELEV_BIG_W, ELEV_BIG_H, true);

    /* 横轴：0 / 1 km / 2 km。 */
    (void)B(s_scr, 24, 210, 192, 1, P_HAIR, LV_OPA_COVER, 0);
    L(s_scr, "0", PX_MICRO, P_MUTE, 24, 212);
    LW(s_scr, "1 km", PX_MICRO, P_MUTE, 96, 212, 48, LV_TEXT_ALIGN_CENTER);
    LW(s_scr, "2 km", PX_MICRO, P_MUTE, 168, 212, 48, LV_TEXT_ALIGN_RIGHT);

    snprintf(buf, sizeof(buf), "%.1f", (s_elev[1] - s_elev[0]) / step * 100.0);
    elev_stat(24, "当前坡度", buf, "%");
    snprintf(buf, sizeof(buf), "%d", (int)lround(gain));
    elev_stat(96, "累计爬升", buf, "m");
    snprintf(buf, sizeof(buf), "%d", (int)lround(mx));
    elev_stat(168, "最高点", buf, "m");
    snprintf(buf, sizeof(buf), "最高点在前方 %.1f km",
             (double)peak * step / 1000.0);
    LW(s_scr, buf, PX_MICRO, P_MUTE, 24, 286, 192, LV_TEXT_ALIGN_CENTER);
}

static void ride_refresh(void)
{
    char buf[32];

    if (UR.arc == NULL) {
        return;
    }
    lv_arc_set_value(UR.arc, (int)lround(R.speed));
    snprintf(buf, sizeof(buf), "%.1f", R.speed);
    lv_label_set_text(UR.hero, buf);
    snprintf(buf, sizeof(buf), "%d", R.hr);
    if (UR.hr_val != NULL) {
        lv_label_set_text(UR.hr_val, buf);
    }
    {
        int x = 52 + (int)lround(164.0 * R.speed / 60.0) - 1;

        if (x < 53) x = 53;
        if (x > 212) x = 212;
        lv_obj_set_x(UR.cursor, x);
    }
    {
        const int z = hr_zone(R.hr);
        static const uint32_t zc[5] = { 0xD6D2CEu, 0xCED7E6u, 0xC5DBCEu,
                                        0xEFD7C5u, 0xE8CCC4u };
        static const uint32_t zd[5] = { 0x8F8A7Fu, 0x1C63B0u, 0x0B6E4Fu,
                                        0xBD5908u, 0xA62B1Fu };

        for (int i = 0; i < 5; i++) {
            lv_obj_set_style_bg_color(UR.hr[i],
                                      lv_color_hex(i == z - 1 ? zd[i] : zc[i]),
                                      0);
        }
        lv_obj_set_x(UR.hr_b1, 96 + (z - 1) * 24);
        lv_obj_set_x(UR.hr_b2, 96 + z * 24);
        snprintf(buf, sizeof(buf), "心率 Z%d", z);
        lv_label_set_text(UR.hr_z, buf);
    }
    {
        const char *vals[4];
        char b0[24], b1[24], b2[24], b3[24];

        if (s_ride_page == 0) {
            snprintf(b0, sizeof(b0), "%.1f", R.dist_km);
            snprintf(b1, sizeof(b1), "%u:%02u",
                     (unsigned)(R.elapsed_s / 60),
                     (unsigned)(R.elapsed_s % 60));
            snprintf(b2, sizeof(b2), "%d", R.cadence);
            snprintf(b3, sizeof(b3), "%d", R.elevation);
            vals[0] = b0; vals[1] = b1; vals[2] = b2; vals[3] = b3;
        } else if (s_ride_page == 1) {
            snprintf(b0, sizeof(b0), "%.1f", R.avg);
            snprintf(b1, sizeof(b1), "%.1f", R.max);
            snprintf(b2, sizeof(b2), "%d", R.cal);
            snprintf(b3, sizeof(b3), "%d", R.ascent);
            vals[0] = b0; vals[1] = b1; vals[2] = b2; vals[3] = b3;
        } else {
            snprintf(b0, sizeof(b0), "%d", R.hr);
            snprintf(b1, sizeof(b1), "Z%d", hr_zone(R.hr));
            snprintf(b2, sizeof(b2), "%.1f", R.avg);
            snprintf(b3, sizeof(b3), "%d", R.cadence);
            vals[0] = b0; vals[1] = b1; vals[2] = b2; vals[3] = b3;
        }
        for (int i = 0; i < 4; i++) {
            lv_label_set_text(UR.metrics[i], vals[i]);
        }
    }
    for (int i = 0; i < 3; i++) {
        lv_obj_set_style_bg_color(UR.dots[i],
                                  lv_color_hex(i == s_ride_page ? C_DEEP[M_RIDE]
                                                                : P_TRACK),
                                  0);
    }
}

