static void rec_week_bars(void)
{
    double mx = 1.0;

    for (int i = 0; i < 7; i++) {
        if (s_week[i] > mx) mx = s_week[i];
    }
    for (int i = 0; i < 7; i++) {
        int h = s_week[i] == 0.0 ? 2 : (int)((s_week[i] * 26.0) / mx);

        if (h < 2) h = 2;
        lv_obj_set_height(UC.week[i], h);
        lv_obj_set_y(UC.week[i], 88 - h);
        lv_obj_set_style_bg_color(UC.week[i],
                                  lv_color_hex(s_week[i] == 0 ? P_TRACK
                                                              : C_DEEP[M_RECORD]),
                                  0);
