static void rec_row_value_layout(int i)
{
    const int y = 104 + i * 46;
    const char *txt = lv_label_get_text(UC.dist[i]);
    const int tw = text_width(txt, PX_VALUE);
    const int uw = text_width("km", PX_MICRO);
    const int ux = 188 - uw;        /* 单位右端 188，给迷你柱留 192..216 */
    const int vx = ux - 4 - tw;

    lv_obj_set_x(UC.dist[i], vx);
    lv_obj_set_pos(UC.dist_unit[i], ux, y + 19);
}

static void rec_rows(void)
{
    int n = s_rec_n < 4 ? s_rec_n : 4;

    for (int i = 0; i < 4; i++) {
        if (i < n) {
            char buf[24];

            lv_label_set_text(UC.date[i], s_recs[i].date);
            lv_label_set_text(UC.sub[i], s_recs[i].sub);
            snprintf(buf, sizeof(buf), "%.1f", s_recs[i].dist);
