static lv_obj_t *opt_chip(lv_obj_t *p, int cx, int cy, int d, uint32_t light,
                          uint32_t deep, bool border)
{
    lv_obj_t *b = B(p, cx - d / 2, cy - d / 2, d, d, light, LV_OPA_COVER,
                    d / 2);

    if (border) {
        lv_obj_set_style_border_width(b, 1, 0);
        lv_obj_set_style_border_color(b, lv_color_hex(deep), 0);
        lv_obj_set_style_border_opa(b, LV_OPA_COVER, 0);
    }
    return b;
}

static void iconopt_row(int y, char opt)
{
    static const char *const lab[3] = {
        "A 无底色 · 图标 26px（采用）",
        "B 正圆 ∮28 · 图标 20px",
        "C 竖排 · 图标在上 · 无框",
    };
    const int i = (opt == 'A') ? 0 : (opt == 'B') ? 1 : 2;
    const uint32_t deep = C_DEEP[M_NAV];
    const uint32_t light = C_LIGHT[M_NAV];

    L(s_scr, lab[i], PX_MICRO, P_MUTE, 24, y);
    if (opt == 'A') {
        /* 26px 图标按 30px 字的字面高取，直接放在文字左侧。 */
        (void)LW(s_scr, "导航", PX_TITLE, P_INK, 0, y + 30, 240,
                 LV_TEXT_ALIGN_CENTER);
        (void)hfi_create_px(s_scr, HELM_ICON_NAV, 26, 71, y + 50, deep);
    } else if (opt == 'B') {
        /* 正圆直径 = 字面高 28，图标 20px（≈60%），1px 深色边。 */
        (void)opt_chip(s_scr, 70, y + 50, 28, light, deep, true);
        (void)hfi_create(s_scr, HELM_ICON_NAV, 70, y + 50, deep);
        (void)LW(s_scr, "导航", PX_TITLE, P_INK, 0, y + 30, 240,
                 LV_TEXT_ALIGN_CENTER);
    } else {
        /* 竖排：图标在上，浅底只做底、不做边框。 */
        (void)opt_chip(s_scr, 120, y + 34, 28, light, deep, false);
        (void)hfi_create(s_scr, HELM_ICON_NAV, 120, y + 34, deep);
        (void)LW(s_scr, "导航", PX_TITLE, P_INK, 0, y + 46, 240,
                 LV_TEXT_ALIGN_CENTER);
    }
}

