/** @brief 录制、暂停或导航中：用骑行翻页（数据/地图/转向/爬升）。 */
static bool helm_in_session(void)
{
    return helm_riding() || helm_nav_on();
}

static uint8_t * helm_active_idx(void)
{
    return helm_in_session() ? &s_sh.ride_idx : &s_sh.home_idx;
}

