{
    return tool_alt_flip(1);
}

static uint8_t sys_pct(uint64_t part, uint64_t total)
{
    if (total == 0) {
        return 0;
    }

    if (part >= total) {
        return 100;
    }

    return (uint8_t)((part * 100ull + total / 2ull) / total);
}

