    helm_kv_add(kv, HELM_ICO_CHIP, "硬件", line);
    helm_kv_add(kv, HELM_ICO_BLE, "蓝牙名",
                (id && id[0]) ? id : VERSION_FIRMWARE_NAME);
    helm_kvbox_seal(kv);
}

